contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(true);

        bool success1;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success1 = false;
        } else {
            success1 = true;
        }

        bool success2;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            success2 = false;
        } else {
            success2 = true;
        }

        // At most one of the two calls may succeed: the bonus can be
        // claimed at most once per recipient.
        assert(!success1 || !success2);
    }

    receive() external payable {}
}

